begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,other_property uuid,actor_id uuid,competitor_id uuid,archived_id uuid,foreign_competitor uuid,unit_id uuid,capture_id uuid);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision reporting rollback fixture'from fixture union all select other_property,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision other reporting rollback fixture'from fixture;
insert into public.competitors(id,property_id,name,is_active)select competitor_id,property_id,'Reporting competitor',true from fixture union all select archived_id,property_id,'Archived reporting competitor',false from fixture union all select foreign_competitor,other_property,'Other reporting competitor',true from fixture;
insert into public.market_source_captures(id,property_id,competitor_id,source_type,source_url,raw_ref,status,captured_at,effective_at)select capture_id,property_id,competitor_id,'manual','https://example.com/pricing','private-only receipt reference','captured',statement_timestamp()-interval '20 days',null from fixture;
insert into public.competitor_units(id,competitor_id,unit_type,bedrooms,rent_min,rent_max,available_count,capture_id)select unit_id,competitor_id,'Primary',0,0,null,null,capture_id from fixture;
insert into public.competitor_units(competitor_id,unit_type,bedrooms,rent_min)select f.competitor_id,'Plan '||n,1,case when n=1004 then null else 1000 end from fixture f cross join generate_series(1,1004)n;
insert into public.competitor_units(competitor_id,unit_type,bedrooms,rent_min)select archived_id,'Excluded archived',1,9999 from fixture union all select foreign_competitor,'Excluded other',1,9999 from fixture;
insert into public.competitor_price_history(competitor_unit_id,rent_min,recorded_at,capture_id,source)select unit_id,1000,statement_timestamp()-interval '40 days',capture_id,'manual'from fixture union all select unit_id,1200,statement_timestamp()-interval '31 days',capture_id,'manual'from fixture union all select unit_id,1400,statement_timestamp()-interval '2 days',capture_id,'manual'from fixture union all select unit_id,9999,statement_timestamp()+interval '2 days',capture_id,'manual'from fixture;
do $$declare f fixture;r jsonb;before_count integer;begin select * into f from fixture;
 perform pg_temp.check(not has_function_privilege('authenticated','public.read_marketvision_analysis(uuid,uuid,integer)','execute')and not has_function_privilege('anon','public.read_marketvision_analysis(uuid,uuid,integer)','execute'),'only scoped service reads may call complete snapshots');
 perform pg_temp.check(public.read_marketvision_analysis(f.property_id,gen_random_uuid(),30)->>'state'='forbidden','unknown actors cannot read');
 perform pg_temp.check(public.read_marketvision_analysis(gen_random_uuid(),f.actor_id,30)->>'state'='forbidden','unknown properties cannot read');
 select count(*)into before_count from public.shared_action_events where property_id=f.property_id;
 r:=public.read_marketvision_analysis(f.property_id,f.actor_id,30);
 perform pg_temp.check(r->>'state'='ready','complete snapshot is returned');
 perform pg_temp.check(jsonb_array_length(r->'units')=1005,'all 1005 plans survive REST row limits');
 perform pg_temp.check(jsonb_array_length(r->'competitors')=1 and r->'competitors'->0->>'id'=f.competitor_id::text,'archived and other-property competitors excluded');
 perform pg_temp.check(not exists(select 1 from jsonb_array_elements(r->'units')u where u->>'competitor_id'<>f.competitor_id::text),'all plans belong to selected active competitors');
 perform pg_temp.check(jsonb_array_length(r->'history')=2,'history includes full window and one prior baseline but no future rows');
 perform pg_temp.check((r->'history'->0->>'rent_min')::numeric=1200 and (r->'history'->1->>'rent_min')::numeric=1400,'latest prior observation is retained as the baseline');
 perform pg_temp.check(jsonb_array_length(r->'captures')=1 and not(r->'captures'->0 ? 'raw_ref'),'capture metadata omits private receipt reference');
 perform pg_temp.check(r->'captures'->0->'effective_at'='null'::jsonb and r->'captures'->0->>'fetched'='false','manual capture is not a verified page fetch and does not gain an effective date');
 perform pg_temp.check(exists(select 1 from jsonb_array_elements(r->'units')u where u->>'id'=f.unit_id::text and u->'rent_min'='0'::jsonb and u->'rent_max'='null'::jsonb and u->'available_count'='null'::jsonb),'known zero and unknown values remain distinct');
 perform pg_temp.check((r->>'snapshotAt')::timestamptz-(r->>'windowStart')::timestamptz=interval '30 days','window uses the exact snapshot timestamp');
 perform pg_temp.check((select count(*)=before_count from public.shared_action_events where property_id=f.property_id),'viewing reports does not mutate pricing or decisions');
 perform pg_temp.check(public.read_marketvision_analysis(f.other_property,f.actor_id,30)->'history'='[]'::jsonb,'a separate property has no leaked pricing history');
 insert into public.competitor_price_history(competitor_unit_id,rent_min,recorded_at)select f.unit_id,1300,recorded_at from public.competitor_price_history where competitor_unit_id=f.unit_id and rent_min=1200;
 perform pg_temp.check(jsonb_array_length(public.read_marketvision_analysis(f.property_id,f.actor_id,30)->'history')=3,'same-time conflicting baseline records are retained for ambiguity checks');
 update public.profiles set org_id=null where id=f.actor_id;
 perform pg_temp.check(public.read_marketvision_analysis(f.property_id,f.actor_id,30)->>'state'='forbidden','reads recheck current membership');
 update public.profiles set org_id='22222222-2222-2222-2222-222222222222'where id=f.actor_id;
 begin perform public.read_marketvision_analysis(f.property_id,f.actor_id,367);raise exception 'expected invalid range';exception when others then if sqlerrm='expected invalid range'then raise;end if;end;
 begin perform public.read_marketvision_analysis(f.property_id,f.actor_id,null);raise exception 'expected invalid range';exception when others then if sqlerrm='expected invalid range'then raise;end if;end;
 perform pg_temp.check(true,'unsupported and missing ranges are rejected');
end$$;
select count(*)as passed_assertions from checks;
rollback;
